<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span>Good Return Note</span>
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <div v-if="loading_spinner" v-html="tableShimmer()"></div>

    <div v-else-if="!note" class="text-center text-muted my-5">
      Return Note not found.
    </div>

    <template v-else>
      <div class="d-flex justify-content-between align-items-center mb-3">
        <h4 class="flex-grow-1 text-center">{{ store.project }} - {{ store.name }}</h4>
        <a
          href="javascript:void(0);"
          class="text-secondary position-relative me-2"
          @click="noteModalRef.open(null, note.id)"
        >
          <i class="bi bi-journal-bookmark-fill fs-5"></i>
          <span
            v-if="note.logs_count > 0"
            class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
            style="font-size: 9px; min-width: 16px; padding: 2px 4px"
          >
            {{ note.logs_count }}
          </span>
        </a>
      </div>

      <form v-if="note.status_id === 9" @submit.prevent="receiverRemark(note)">
        <div class="row layout-top-spacing">
          <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
            <div class="panel p-0">
              <div class="custom-table table3">
                <table class="table table-bordered mb-4">
                  <thead>
                    <tr>
                      <th>Item</th>
                      <th>Returned Quantity</th>
                      <th>Received Quantity</th>
                      <th>Remark</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="(item, idx) in storeItems" :key="item.id || idx">
                      <td>{{ item.item }}</td>
                      <td>{{ item.returned_quantity }}</td>
                      <td>
                        <input
                          type="number"
                          class="form-control"
                          v-model="item.received_quantity"
                          placeholder="Enter received quantity"
                          min="0"
                          required
                        />
                      </td>
                      <td>
                        <input
                          type="text"
                          class="form-control"
                          v-model="item.remark"
                          placeholder="Enter Remark"
                        />
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>

        <textarea
          class="form-control"
          placeholder="Enter General Remarks"
          v-model="remark"
        ></textarea>

        <div class="d-flex mt-2">
          <button type="button" class="btn btn-secondary me-2" @click="$router.back()">
            Close
          </button>
          <div class="ms-auto">
            <button type="submit" class="btn btn-primary mt-1" :disabled="sending">
              <span v-if="sending" v-html="loadingSpinner()"></span>
              <span v-else>Submit</span>
            </button>
          </div>
        </div>
      </form>

      <template v-else>
        <div class="row layout-top-spacing">
          <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
            <div class="panel p-0">
              <div class="custom-table table3">
                <v-client-table :data="storeItems" :columns="itemsColumns" :options="table_option" />
              </div>
            </div>
          </div>
        </div>

        <div v-if="note.remark" class="mb-3">
          <label class="form-label fw-bold">Remark:</label>
          <div class="border rounded p-3 bg-light">{{ note.remark }}</div>
        </div>

        <div class="text-end">
          <button type="button" class="btn btn-secondary" @click="$router.back()">
            Close
          </button>
        </div>
      </template>
    </template>

    <NoteModal
      ref="noteModalRef"
      :source-id="note?.id"
      source="GRT"
      module="GOOD RETURN NOTES"
      title="Grt"
      @logs-updated="(count) => (note.logs_count = count)"
    />
  </div>
</template>

<script setup>
import { ref, inject, onMounted } from "vue";
import { useRoute, useRouter } from "vue-router";
import axios from "axios";
import { useMeta } from "@/composables/use-meta";
import NoteModal from "@/components/reusables/NoteModal.vue";

useMeta({ title: "Return Note Preview" });

const route = useRoute();
const router = useRouter();
const noteModalRef = ref(null);

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const showMessage = inject("showMessage");
const showError = inject("showError");
const tableShimmer = inject("tableShimmer");
const loadingSpinner = inject("loadingSpinner");
const formatDate = inject("formatDate");

const user = JSON.parse(localStorage.getItem("user"));

const loading_spinner = ref(false);
const sending = ref(false);
const remark = ref("");

const itemsColumns = ref(["SNo", "item", "returned_quantity", "received_quantity", "remark"]);
const table_option = ref({
  perPage: 100,
  perPageValues: [100, 200, 500],
  skin: "table table-hover table-striped",
  columnsClasses: { actions: "actions text-center" },
  sortable: [],
  sortIcon: { base: "sort-icon-none", up: "sort-icon-asc", down: "sort-icon-desc" },
  pagination: { nav: "scroll", chunk: 5 },
  texts: {
    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: false,
});

const store = ref("");
const note = ref(null);
const storeItems = ref([]);

const getReturnNote = async () => {
  loading_spinner.value = true;
  try {
    const { data } = await axiosInstance.get(
      `good-return-notes?return_note_id=${route.params.return_note_id}`
    );
    const record = data?.[0];

    if (!record) {
      note.value = null;
      return;
    }

    const mapped = {
      ...record,
      return_no: record.id,
      source_store_id: record.source_store?.id,
      destination_store_id: record.destination_store?.id,
      project: record.source_store?.project?.short_name ?? "",
      name: record.source_store?.name ?? "",
      issuer: record.issuer?.name,
      receiver: record?.receiver?.name,
      date_returned: formatDate(record.created_at),
    };

    store.value = mapped;
    note.value = mapped;

    storeItems.value = record.items.map((item, index) => ({
      ...item,
      SNo: index + 1,
      item: item.item.name,
    }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading_spinner.value = false;
  }
};

const receiverRemark = async (n) => {
  sending.value = true;
  const payload = {
    destination_store: n.destination_store_id,
    status_id: 10,
    receiver_id: user.id,
    source_store: store.value.source_store,
    remark: remark.value,
    items: storeItems.value.map((item) => ({
      id: item.id,
      item_id: item.item_id,
      received_quantity: item.received_quantity,
      remark: item.remark,
    })),
  };

  try {
    await axiosInstance.put(`good-return-notes/${n.id}`, payload);
    showMessage("remark saved");
    const message =
      JSON.parse(localStorage.getItem("user")).name + " Received items from " + n.source_store;
    const receiver = "255698267662";
    const message_id =
      "wamid.HBgMMjU1Njk4MjY3NjYyFQIAEhgWM0VCMDE4NkNGOENGMzEwRDNGQzJFRAA=";
    whatsappAlert(message, message_id, receiver);
    router.back();
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    sending.value = false;
  }
};

onMounted(getReturnNote);
</script>